params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }

$targets=@(
 'integration/smart-pack-planner-main-r2-20260929',
 'integration/smart-pack-planner-main-20260929',
 'agent/smart-pack-planner-core',
 'fix/release-classifier-workflow-scope-20260929'
)

$worktrees=@{}
$path=$null
foreach($line in @(git worktree list --porcelain)){
  if($line -like 'worktree *'){ $path=$line.Substring(9) }
  elseif($line -like 'branch refs/heads/*' -and $path){ $worktrees[$line.Substring(18)]=$path }
  elseif([string]::IsNullOrWhiteSpace($line)){ $path=$null }
}

$deleted=@(); $skipped=@()
foreach($b in $targets){
  git show-ref --verify --quiet "refs/remotes/origin/$b"
  if($LASTEXITCODE -ne 0){ continue }

  if($worktrees.ContainsKey($b)){
    $wt=$worktrees[$b]
    $dirty=@(git -C $wt status --porcelain)
    if($dirty.Count -gt 0){
      $skipped += [ordered]@{branch=$b;reason='dirty-active-worktree';worktree=$wt}
      continue
    }
    git worktree remove --force $wt
    if($LASTEXITCODE -ne 0){
      $skipped += [ordered]@{branch=$b;reason='clean-worktree-remove-failed';worktree=$wt}
      continue
    }
    git show-ref --verify --quiet "refs/heads/$b"
    if($LASTEXITCODE -eq 0){ git branch -D $b | Out-Null }
  }

  git push origin --delete $b
  if($LASTEXITCODE -eq 0){ $deleted += $b }
  else { $skipped += [ordered]@{branch=$b;reason='remote-delete-failed'} }
}

git fetch origin --prune | Out-Null
[ordered]@{
  deleted=$deleted
  skipped=$skipped
  remaining_remote_count=@(git for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object {$_ -ne 'origin/HEAD'}).Count
  main=(git rev-parse origin/main | Out-String).Trim()
} | ConvertTo-Json -Depth 4
